"""Multi-file fixtures and reference changes; generated by generate.py."""
import difflib
import json
from textwrap import dedent

def add_hard_tasks(add, write, tasks):
    def hard(id, repo, category, prompt, command, files, changes, extra=None):
        files={path:dedent(text).lstrip('\n') for path,text in files.items()}
        for path,text in files.items():
            write(f'repos/{repo}/{path}',text)
        add(id,repo,category,prompt+' Run '+command+'.',command,'.answer','','',extra)
        tasks[-1]['tags'].append('hard')
        write(f'tasks/{id}.json',json.dumps(tasks[-1],indent=2)+'\n')
        patch=''
        for path,text in changes.items():
            before=files.get(path,'')
            after=dedent(text).lstrip('\n')
            patch+=''.join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile='a/'+path if before else '/dev/null',tofile='b/'+path))
        write(f'solutions/{id}.patch',patch)

    hard('ts-bugfix-reservations','ts-lib','bugfix',
         'Investigate the failing inventory tests in hard/inventory. Stock identity is the exact (SKU, warehouse) pair; either string may contain colons. Fix batch reservations so duplicate lines are aggregated and the entire batch is atomic on failure. Preserve the Store and reserve APIs and never mutate requests.',
         'node --test hard/inventory/check.test.ts',{
        'hard/inventory/store.ts': '''
            export type Line = {sku:string; warehouse:string; quantity:number};
            const key = (sku:string, warehouse:string) => `${sku}:${warehouse}`;
            export class Store {
              stock = new Map<string,number>();
              get(sku:string,warehouse:string) { return this.stock.get(key(sku,warehouse)) ?? 0; }
              set(sku:string,warehouse:string,quantity:number) { this.stock.set(key(sku,warehouse),quantity); }
            }
        ''',
        'hard/inventory/reserve.ts': '''
            import {Store, type Line} from './store.ts';
            export function reserve(store:Store, lines:Line[]):boolean {
              for(const line of lines) {
                if(!Number.isInteger(line.quantity) || line.quantity<0) throw new RangeError('quantity');
                if(store.get(line.sku,line.warehouse)<line.quantity) return false;
              }
              for(const line of lines) store.set(line.sku,line.warehouse,store.get(line.sku,line.warehouse)-line.quantity);
              return true;
            }
        ''',
        'hard/inventory/check.test.ts': '''
            import {test} from 'node:test';
            import assert from 'node:assert/strict';
            import {Store} from './store.ts';
            import {reserve} from './reserve.ts';
            test('identity isolation across compound keys',()=>{
              const s=new Store(); s.set('a:b','c',9); s.set('a','b:c',4); s.set('c','a:b',7);
              assert.equal(reserve(s,[{sku:'a:b',warehouse:'c',quantity:3}]),true);
              assert.equal(s.get('a:b','c'),6); assert.equal(s.get('a','b:c'),4); assert.equal(s.get('c','a:b'),7);
            });
            test('duplicates cannot overdraw and failure is atomic',()=>{
              const s=new Store(); s.set('x','w',5); s.set('y','w',10);
              const rows=[{sku:'y',warehouse:'w',quantity:2},{sku:'x',warehouse:'w',quantity:3},{sku:'x',warehouse:'w',quantity:3}];
              const copy=structuredClone(rows);
              assert.equal(reserve(s,rows),false); assert.deepEqual(rows,copy);
              assert.equal(s.get('x','w'),5); assert.equal(s.get('y','w'),10);
              rows[2].quantity=2; assert.equal(reserve(s,rows),true); assert.equal(s.get('x','w'),0); assert.equal(s.get('y','w'),8);
            });
            test('invalid later lines do not partially write; empty and zero batches work',()=>{
              const s=new Store(); s.set('x','w',5);
              for(const quantity of [-1,0.5,NaN,Infinity]) {
                assert.throws(()=>reserve(s,[{sku:'x',warehouse:'w',quantity:2},{sku:'x',warehouse:'w',quantity}]),RangeError);
                assert.equal(s.get('x','w'),5);
              }
              assert.equal(reserve(s,[]),true); assert.equal(reserve(s,[{sku:'absent',warehouse:'w',quantity:0}]),true);
              assert.equal(reserve(s,[{sku:'absent',warehouse:'w',quantity:1}]),false);
            });
        ''',
    },{
        'hard/inventory/store.ts': '''
            export type Line = {sku:string; warehouse:string; quantity:number};
            const key = (sku:string, warehouse:string) => JSON.stringify([sku,warehouse]);
            export class Store {
              stock = new Map<string,number>();
              get(sku:string,warehouse:string) { return this.stock.get(key(sku,warehouse)) ?? 0; }
              set(sku:string,warehouse:string,quantity:number) { this.stock.set(key(sku,warehouse),quantity); }
            }
        ''',
        'hard/inventory/reserve.ts': '''
            import {Store, type Line} from './store.ts';
            export function reserve(store:Store, lines:Line[]):boolean {
              const totals=new Map<string,Line>();
              for(const line of lines) {
                if(!Number.isInteger(line.quantity) || line.quantity<0) throw new RangeError('quantity');
                const key=JSON.stringify([line.sku,line.warehouse]);
                totals.set(key,{...line,quantity:(totals.get(key)?.quantity??0)+line.quantity});
              }
              for(const line of totals.values()) if(store.get(line.sku,line.warehouse)<line.quantity) return false;
              for(const line of totals.values()) store.set(line.sku,line.warehouse,store.get(line.sku,line.warehouse)-line.quantity);
              return true;
            }
        ''',
    })

    hard('ts-feature-discount','ts-lib','feature',
         'Implement allocateDiscount(amounts, discountCents) in hard/invoice/money.ts. Return per-line integer discounts proportional to the amounts using largest remainders; ties go to earlier lines. Do not mutate inputs. Reject noninteger/negative amounts or discounts and discounts exceeding the total; an all-zero or empty order accepts only zero. Update both checkout and quote to use it so totals reconcile. Add a direct allocator test in hard/invoice/money.test.ts. Read the failing integration tests first.',
         'node --test hard/invoice/*.test.ts',{
        'hard/invoice/money.ts': 'export const sum = (xs:number[]) => xs.reduce((a,b)=>a+b,0);\n',
        'hard/invoice/checkout.ts': '''
            export function checkout(amounts:number[],discount:number) {
              return amounts.map(amount=>amount-discount);
            }
        ''',
        'hard/invoice/quote.ts': '''
            import {sum} from './money.ts';
            export function quote(lines:{id:string; cents:number}[],discount:number) {
              const items=lines.map(line=>({...line,cents:line.cents-discount}));
              return {items,total:sum(items.map(line=>line.cents))};
            }
        ''',
        'hard/invoice/check.test.ts': '''
            import {test} from 'node:test';
            import assert from 'node:assert/strict';
            import {checkout} from './checkout.ts';
            import {quote} from './quote.ts';
            import * as money from './money.ts';
            test('both consumers reconcile proportional rounding and stable ties',()=>{
              for(const [amounts,discount,want] of [[[101,101,101],2,[100,100,101]],[[100,300],101,[75,224]],[[0,5],3,[0,2]],[[3,7],10,[0,0]],[[],0,[]],[[0,0],0,[0,0]]] as [number[],number,number[]][]) {
                const copy=[...amounts]; const lines=amounts.map((cents,i)=>({id:String(i),cents}));
                assert.deepEqual(checkout(amounts,discount),want);
                const q=quote(lines,discount); assert.deepEqual(q.items,lines.map((line,i)=>({...line,cents:want[i]})));
                assert.equal(q.total,money.sum(amounts)-discount); assert.deepEqual(amounts,copy);
              }
            });
            test('public allocator and validation agree at both call sites',()=>{
              assert.equal(typeof money.allocateDiscount,'function');
              assert.deepEqual(money.allocateDiscount([1,1,1],1),[1,0,0]);
              for(const [xs,d] of [[[1],2],[[-1],0],[[1.5],1],[[1],-1],[[1],0.5],[[0],1],[[NaN],0],[[1],Infinity]] as [number[],number][]) {
                assert.throws(()=>money.allocateDiscount(xs,d),RangeError);
                assert.throws(()=>checkout(xs,d),RangeError);
                assert.throws(()=>quote(xs.map(cents=>({id:'a',cents})),d),RangeError);
              }
            });
        ''',
    },{
        'hard/invoice/money.ts': '''
            export const sum = (xs:number[]) => xs.reduce((a,b)=>a+b,0);
            export function allocateDiscount(amounts:number[],discount:number):number[] {
              const total=sum(amounts);
              if(!Number.isInteger(discount)||discount<0||amounts.some(n=>!Number.isInteger(n)||n<0)||discount>total) throw new RangeError('discount');
              if(total===0) return amounts.map(()=>0);
              const exact=amounts.map(n=>n*discount/total);
              const shares=exact.map(Math.floor);
              const order=exact.map((n,i)=>({i,fraction:n-shares[i]})).sort((a,b)=>b.fraction-a.fraction||a.i-b.i);
              const remaining=discount-sum(shares);
              for(let i=0;i<remaining;i++) shares[order[i].i]++;
              return shares;
            }
        ''',
        'hard/invoice/checkout.ts': '''
            import {allocateDiscount} from './money.ts';
            export function checkout(amounts:number[],discount:number) {
              const shares=allocateDiscount(amounts,discount);
              return amounts.map((amount,i)=>amount-shares[i]);
            }
        ''',
        'hard/invoice/quote.ts': '''
            import {sum,allocateDiscount} from './money.ts';
            export function quote(lines:{id:string; cents:number}[],discount:number) {
              const shares=allocateDiscount(lines.map(line=>line.cents),discount);
              const items=lines.map((line,i)=>({...line,cents:line.cents-shares[i]}));
              return {items,total:sum(items.map(line=>line.cents))};
            }
        ''',
        'hard/invoice/money.test.ts': '''
            import {test} from 'node:test';
            import assert from 'node:assert/strict';
            import {allocateDiscount} from './money.ts';
            test('allocator handles remainders without mutating frozen input',()=>{
              const amounts=Object.freeze([2,3,5]);
              assert.deepEqual(allocateDiscount(amounts as unknown as number[],3),[1,1,1]);
            });
        ''',
    },[{'file':'hard/invoice/money.test.ts','contains':'allocateDiscount'}])

    hard('py-bugfix-stdin','py-cli','bugfix',
         'Fix hard_cli argument/stream handling. With no paths, read stdin. A single - consumes stdin at its exact position among UTF-8 files; repeated - is a usage error. -- must allow a filename beginning with -. --limit N limits the concatenated lines and must be nonnegative. Emit one JSON array on stdout; file/usage errors exit 2 with stderr and no traceback or partial stdout. Empty stdin yields []. Preserve line text and ordering. Run the tests and inspect their subprocess failures.',
         'python3 -m unittest hard_cli.test_cli',{
        'hard_cli/__init__.py':'',
        'hard_cli/reader.py': '''
            from pathlib import Path
            def read_inputs(paths, stdin):
                return [line for path in paths for line in Path(path).read_text(encoding='utf-8').splitlines()]
        ''',
        'hard_cli/cli.py': '''
            import argparse
            import json
            import sys
            from .reader import read_inputs
            def main():
                parser=argparse.ArgumentParser()
                parser.add_argument('--limit',type=int)
                parser.add_argument('paths',nargs='*')
                args=parser.parse_args()
                rows=read_inputs(args.paths,sys.stdin)
                print(json.dumps(rows[:args.limit]))
            if __name__ == '__main__':
                main()
        ''',
        'hard_cli/test_cli.py': '''
            import json
            import os
            from pathlib import Path
            import subprocess
            import sys
            import tempfile
            import unittest
            class Tests(unittest.TestCase):
                def run_cli(self,args,text='',cwd=None):
                    env={**os.environ,'PYTHONPATH':str(Path(__file__).resolve().parent.parent)}
                    return subprocess.run([sys.executable,'-m','hard_cli.cli',*args],input=text,text=True,capture_output=True,cwd=cwd,env=env,timeout=3)
                def success(self,result,want):
                    self.assertEqual(result.returncode,0,result.stderr)
                    self.assertEqual(result.stderr,'')
                    self.assertEqual(json.loads(result.stdout),want)
                def test_default_stdin_and_empty(self):
                    self.success(self.run_cli([],' a \\nβ\\n'),[' a ','β'])
                    self.success(self.run_cli([],''),[])
                    self.success(self.run_cli(['--limit','0'],'x\\n'),[])
                def test_stream_order_limit_and_dash_filename(self):
                    with tempfile.TemporaryDirectory() as d:
                        Path(d,'one').write_text('first\\n')
                        Path(d,'-last').write_text('last\\n')
                        self.success(self.run_cli(['--limit','3','--','one','-','-last'],'middle\\nextra\\n',d),['first','middle','extra'])
                        self.success(self.run_cli(['--','-last'],'ignored',d),['last'])
                        self.success(self.run_cli(['one','-'],'middle\\n',d),['first','middle'])
                def test_errors_are_atomic_usage_errors(self):
                    for args in [['-','-'],['--limit','-1'],['--limit','no'],['--unknown'],['missing-file']]:
                        result=self.run_cli(args,'must not leak\\n')
                        self.assertEqual(result.returncode,2,result.stderr)
                        self.assertEqual(result.stdout,'')
                        self.assertIn('error:',result.stderr)
                        self.assertNotIn('Traceback',result.stderr)
        ''',
    },{
        'hard_cli/reader.py': '''
            from pathlib import Path
            def read_inputs(paths, stdin):
                paths=paths or ['-']
                if paths.count('-')>1:
                    raise ValueError('stdin may appear only once')
                return [line for path in paths for line in (stdin.read() if path=='-' else Path(path).read_text(encoding='utf-8')).splitlines()]
        ''',
        'hard_cli/cli.py': '''
            import argparse
            import json
            import sys
            from .reader import read_inputs
            def main():
                parser=argparse.ArgumentParser()
                parser.add_argument('--limit',type=int)
                parser.add_argument('paths',nargs='*')
                args=parser.parse_args()
                if args.limit is not None and args.limit<0:
                    parser.error('--limit must be nonnegative')
                try:
                    rows=read_inputs(args.paths,sys.stdin)
                except (OSError,ValueError) as error:
                    parser.error(str(error))
                print(json.dumps(rows[:args.limit]))
            if __name__ == '__main__':
                main()
        ''',
    })

    hard('ts-refactor-records','ts-lib','refactor',
         'Refactor hard/records/parser.ts around a new lazy generator parseLines(Iterable<string>). Keep the public parseRecords(text) and parseConfig(text) APIs, whitespace rules, last-key-wins behavior and exact SyntaxError line numbers stable. Both existing functions must delegate to parseLines. Do not consume a source until next() or read ahead; support a one-shot iterable. Preserve the existing API tests and add the new streaming behavior needed by streaming.test.ts.',
         'node --test hard/records/*.test.ts',{
        'hard/records/parser.ts': '''
            export function parseRecords(text:string):{key:string;value:string}[] {
              return text.split('\\n').flatMap((raw,i)=>{
                const line=raw.replace(/\\r$/,'');
                if(!line.trim()||line.trimStart().startsWith('#')) return [];
                const at=line.indexOf('=');
                if(at<1||!line.slice(0,at).trim()) throw new SyntaxError(`Invalid record at line ${i+1}`);
                return [{key:line.slice(0,at).trim(),value:line.slice(at+1)}];
              });
            }
            export function parseConfig(text:string):Record<string,string> {
              return Object.fromEntries(parseRecords(text).map(row=>[row.key,row.value]));
            }
        ''',
        'hard/records/api.test.ts': '''
            import {test} from 'node:test';
            import assert from 'node:assert/strict';
            import {parseRecords,parseConfig} from './parser.ts';
            test('existing public API and errors remain stable',()=>{
              const input=' # comment\\r\\n a = x=y \\r\\n\\n a=last\\n__proto__=safe\\n';
              assert.deepEqual(parseRecords(input),[{key:'a',value:' x=y '},{key:'a',value:'last'},{key:'__proto__',value:'safe'}]);
              assert.deepEqual(parseConfig(input),JSON.parse('{"a":"last","__proto__":"safe"}'));
              assert.deepEqual(parseRecords(''),[]);
              for(const text of ['# ignore\\n\\ninvalid','x=y\\n# comment\\n =empty']) {
                for(const parse of [parseRecords,parseConfig]) assert.throws(()=>parse(text),{name:'SyntaxError',message:'Invalid record at line 3'});
              }
            });
        ''',
        'hard/records/streaming.test.ts': '''
            import {test} from 'node:test';
            import assert from 'node:assert/strict';
            import * as parser from './parser.ts';
            test('lazy consumption, physical lines and one-shot iterators',()=>{
              let consumed=0;
              function* source() { for(const line of ['# skip','a=1','','broken','z=2']) {consumed++;yield line;} }
              assert.equal(typeof parser.parseLines,'function');
              const rows=parser.parseLines(source()); assert.equal(consumed,0);
              assert.deepEqual(rows.next().value,{key:'a',value:'1'}); assert.equal(consumed,2);
              assert.throws(()=>rows.next(),{name:'SyntaxError',message:'Invalid record at line 4'}); assert.equal(consumed,4);
              assert.deepEqual([...parser.parseLines(['a=1','a=2'])],[{key:'a',value:'1'},{key:'a',value:'2'}]);
              for(const fn of [parser.parseRecords,parser.parseConfig]) assert.match(fn.toString(),/parseLines/,'public APIs must use the shared parser');
            });
        ''',
    },{
        'hard/records/parser.ts': '''
            export function* parseLines(lines:Iterable<string>):Generator<{key:string;value:string}> {
              let number=0;
              for(const raw of lines) {
                number++;
                const line=raw.replace(/\\r$/,'');
                if(!line.trim()||line.trimStart().startsWith('#')) continue;
                const at=line.indexOf('=');
                if(at<1||!line.slice(0,at).trim()) throw new SyntaxError(`Invalid record at line ${number}`);
                yield {key:line.slice(0,at).trim(),value:line.slice(at+1)};
              }
            }
            export function parseRecords(text:string):{key:string;value:string}[] {
              return [...parseLines(text.split('\\n'))];
            }
            export function parseConfig(text:string):Record<string,string> {
              return Object.fromEntries([...parseLines(text.split('\\n'))].map(row=>[row.key,row.value]));
            }
        ''',
    })
